import{_ as t,o as a,c as o,a2 as i}from"./chunks/framework.Cz0TtJv6.js";const u=JSON.parse('{"title":"Easy setup (Railway)","description":"One-click Railway deploy for DLMM Bot. Paper first, then live from the dashboard.","frontmatter":{"title":"Easy setup (Railway)","description":"One-click Railway deploy for DLMM Bot. Paper first, then live from the dashboard."},"headers":[],"relativePath":"easy.md","filePath":"easy.md","lastUpdated":1786664618000}'),r={name:"easy.md"};function l(s,e,n,d,c,p){return a(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="easy-setup-railway" tabindex="-1">Easy setup (Railway) <a class="header-anchor" href="#easy-setup-railway" aria-label="Permalink to &quot;Easy setup (Railway)&quot;">​</a></h1><p>One service. Config is automated. You attach a volume once, open the public URL, then finish secrets in our dashboard Settings UI.</p><p><a href="https://railway.com?referralCode=SCj9lN" target="_blank" rel="noreferrer">Sign up on Railway →</a></p><div class="warning custom-block"><p class="custom-block-title">Risk</p><p>Memecoin LP can wipe a wallet. Not financial advice. <strong>Burner only.</strong></p></div><div class="info custom-block"><p class="custom-block-title">Usage fee</p><p><strong>1% of measured net profit</strong> on each live winning close buys+burns <strong>GNME</strong>. Required product fee (hardcoded — not in Settings). Paper does not spend.</p></div><h2 id="what-s-automated" tabindex="-1">What’s automated <a class="header-anchor" href="#what-s-automated" aria-label="Permalink to &quot;What’s automated&quot;">​</a></h2><p>The repo ships a <code>railway.toml</code> so Railway builds the dashboard and runs <strong>farmer + dash together</strong> in one service. On boot it:</p><ul><li>Defaults to <code>FARMER_MODE=paper</code> (safe)</li><li>Listens on Railway’s public <code>PORT</code></li><li>Seeds persistent <code>config.toml</code> + <code>.env</code> on the volume</li><li>Auto-generates a <code>DASH_TOKEN</code> if you didn’t set one (printed in logs)</li></ul><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Volumes still can’t be declared in TOML (Railway limitation). Attaching <code>/app/data</code> once is the only infra click left.</p></div><h2 id="deploy-3-steps" tabindex="-1">Deploy (3 steps) <a class="header-anchor" href="#deploy-3-steps" aria-label="Permalink to &quot;Deploy (3 steps)&quot;">​</a></h2><h3 id="_1-sign-up-deploy-the-repo" tabindex="-1">1. Sign up &amp; deploy the repo <a class="header-anchor" href="#_1-sign-up-deploy-the-repo" aria-label="Permalink to &quot;1. Sign up &amp; deploy the repo&quot;">​</a></h3><p><a href="https://railway.com?referralCode=SCj9lN" target="_blank" rel="noreferrer">railway.com?referralCode=SCj9lN</a> → <strong>New Project → Deploy from GitHub</strong> → <code>CryptoGnome/dlmmbot</code> (or your fork).</p><p>One service is enough. Start/build commands come from <code>railway.toml</code> — you should not need to type them.</p><h3 id="_2-attach-a-volume-at-app-data" tabindex="-1">2. Attach a volume at <code>/app/data</code> <a class="header-anchor" href="#_2-attach-a-volume-at-app-data" aria-label="Permalink to &quot;2. Attach a volume at `/app/data`&quot;">​</a></h3><p>Service → click the service → <strong>Volumes</strong> → Add → mount path <code>/app/data</code>. This keeps SQLite, Settings, and your token across redeploys.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Redeploy after attaching so the mount is live.</p></div><h3 id="_3-generate-a-public-domain" tabindex="-1">3. Generate a public domain <a class="header-anchor" href="#_3-generate-a-public-domain" aria-label="Permalink to &quot;3. Generate a public domain&quot;">​</a></h3><p>Settings → Networking → <strong>Generate domain</strong>. That’s your dashboard URL.</p><h2 id="open-the-dashboard" tabindex="-1">Open the dashboard <a class="header-anchor" href="#open-the-dashboard" aria-label="Permalink to &quot;Open the dashboard&quot;">​</a></h2><p>Open the public URL. If you didn’t set <code>DASH_TOKEN</code>, check <strong>Deploy logs</strong> for <code>[railway] generated DASH_TOKEN=…</code> and paste that token.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Optional but recommended: copy that token into Railway Variables as <code>DASH_TOKEN</code> so it never rotates.</p></div><h2 id="finish-in-our-settings-ui" tabindex="-1">Finish in our Settings UI <a class="header-anchor" href="#finish-in-our-settings-ui" aria-label="Permalink to &quot;Finish in our Settings UI&quot;">​</a></h2><p>First login opens a <strong>setup wizard</strong> for the core pieces (RPC, wallet, mode). With the volume attached, Settings writes to <code>/app/data/config.toml</code> (and <code>.env</code>) — the repo template stays clean so git never shows DIRTY from knobs.</p><ul><li>Leave paper mode until you’re comfortable</li><li>Add private <code>RPC_URL</code> (wizard or Settings → Wallet &amp; secrets)</li><li>Create an encrypted burner wallet under Settings → Wallet &amp; secrets, or import from Phantom — never paste your main wallet</li><li>Optional: set <code>WALLET_PASSPHRASE</code> on Railway to auto-unlock on boot</li><li>Tune token-safety / sizing under Settings → Bot settings (persisted under the volume)</li></ul><div class="danger custom-block"><p class="custom-block-title">Burner only</p><p>Never use your main wallet.</p></div><h2 id="going-live" tabindex="-1">Going live <a class="header-anchor" href="#going-live" aria-label="Permalink to &quot;Going live&quot;">​</a></h2><div class="danger custom-block"><p class="custom-block-title">Real SOL</p><p>Burner only. One farmer process per wallet.</p></div><ul><li>Paper looked sane</li><li>Burner + private RPC + Jupiter set (Settings or Railway Variables)</li><li>Set <code>FARMER_MODE=live</code> (Railway variable or Settings)</li><li>Set <code>[exec] mode = &quot;live&quot;</code> in Settings / config</li><li>Restart / redeploy so both switches are live</li></ul><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Live requires <strong>both</strong> env and config. One alone stays safe.</p></div><h2 id="cost" tabindex="-1">Cost <a class="header-anchor" href="#cost" aria-label="Permalink to &quot;Cost&quot;">​</a></h2><p>Trial credits, then Hobby (~$5) + usage is the realistic always-on floor (volume needs a paid plan tier). <a href="https://railway.com/pricing?referralCode=SCj9lN" target="_blank" rel="noreferrer">Pricing</a>. Own hardware: <a href="./advanced">Advanced</a>.</p><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Symptom</th><th>Fix</th></tr></thead><tbody><tr><td>Build fails on native module</td><td>Node 20 (Railpack default); check <code>better-sqlite3</code> logs</td></tr><tr><td>Dash unauthorized</td><td>Token from logs or Railway <code>DASH_TOKEN</code></td></tr><tr><td>History / Settings wiped</td><td>Volume at <code>/app/data</code>, then redeploy</td></tr><tr><td>Healthcheck failing</td><td>Wait for first build; path is <code>/health</code></td></tr><tr><td>Want local / PM2</td><td><a href="./advanced">Advanced setup</a></td></tr></tbody></table>',33)])])}const m=t(r,[["render",l]]);export{u as __pageData,m as default};
